import{readFile,writeFile,mkdir}from'node:fs/promises';import{createHash}from'node:crypto';
const phase=process.argv[2];if(!['prepare','rollback'].includes(phase))throw Error('Explicit prepare/rollback phase');
const revision=process.argv[3]??'v1';if(!['v1','v2'].includes(revision))throw Error('Explicit supported helper revision');
const root='output/access-legacy-group-role-forward-20261005'+(revision==='v2'?'/revision-02':''),out=root+'/parent-guarded',privateRoot='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925',sha=x=>createHash('sha256').update(x).digest('hex');
const manifest=JSON.parse(await readFile(root+'/FUNCTION-MANIFEST.json','utf8'));
const source=await readFile('output/access-directory-rebased-acceptance-20261005/targeted-rollback/v3-context/PROD-TARGETED-V3-GUARDED-ROLLBACK.sql','utf8');if(sha(source)!=='8ad3bd5a170ff800bd468126c4442289b0edb7b71ceaad21e12a4ed84446829d')throw Error('Known validated preservation source mismatch');
const start=source.indexOf('CREATE TEMP TABLE _fvi_access_old_rows('),end=source.indexOf('-- System catalogues only for auth/storage:');if(start<0||end<=start)throw Error('Exact preservation boundaries');const snapshot=source.slice(start,end);
const preserve=`DO $legacy_old_rows_preserved$ DECLARE old record;actual record;BEGIN FOR old IN SELECT * FROM pg_temp._fvi_access_old_rows LOOP SELECT * INTO STRICT actual FROM pg_temp.fvi_access_rowset(old.schema_name,old.table_name,old.projection);IF actual.row_count<>old.row_count OR actual.row_hash<>old.row_hash THEN RAISE EXCEPTION 'Legacy role helper old data changed: %.%',old.schema_name,old.table_name;END IF;END LOOP;END $legacy_old_rows_preserved$;\n`;
const identity="SELECT current_setting('server_version_num') AS engine,(SELECT count(*)::int FROM supabase_migrations.schema_migrations) AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest,(SELECT md5(prosrc) FROM pg_proc WHERE oid='private.user_has_tenant_role_or_group(uuid,uuid,public.tenant_role)'::regprocedure) AS helper_body_md5";
await mkdir(out,{recursive:true});
const vault=await readFile('./.private/CREDENTIALS.md','utf8'),a=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),z=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||z<=a)throw Error('FVI authority boundary');const token=vault.slice(a,z).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw Error('FVI authority unavailable');
async function query(ref,sql,readonly){const r=await fetch('https://api.supabase.com/v1/projects/'+ref+'/database/query',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:readonly}),signal:AbortSignal.timeout(90000)});const raw=await r.text();if(!r.ok){const file=privateRoot+'/FVI-LEGACY-ROLE-'+phase+'-ERROR-'+Date.now()+'.json';await writeFile(file,JSON.stringify({at:new Date().toISOString(),ref,http:r.status,raw},null,2),{flag:'wx'});throw Error('Legacy helper '+phase+' HTTP'+r.status+'; private diagnostic saved; no commit');}return JSON.parse(raw);}
const results=[];for(const p of manifest.files){if(!['YOUR_PROJECT_REF','YOUR_PROJECT_REF'].includes(p.ref))throw Error('Exact target mismatch');const sqlFile=out+'/'+p.environment+'-GUARDED-ROLLBACK.sql';
 if(phase==='prepare'){const forward=await readFile(root+'/'+p.forward,'utf8');if(sha(forward)!==p.forwardSHA256)throw Error('Frozen forward source changed');const sql="BEGIN;\nSET TRANSACTION ISOLATION LEVEL REPEATABLE READ;\nSET LOCAL lock_timeout='2s';\nSET LOCAL statement_timeout='60s';\n"+snapshot+forward+'\n'+preserve+"SELECT true AS old_rows_preserved,(SELECT count(*) FROM pg_temp._fvi_access_old_rows) AS protected_relations,(SELECT sum(row_count) FROM pg_temp._fvi_access_old_rows) AS protected_rows,(SELECT jsonb_agg(to_jsonb(r) ORDER BY schema_name,table_name) FROM pg_temp._fvi_access_old_rows r) AS old_row_snapshots,(SELECT to_jsonb(p) FROM pg_proc p WHERE oid='private.user_has_tenant_role_or_group(uuid,uuid,public.tenant_role)'::regprocedure) AS post_helper_metadata;\nROLLBACK;\n";await writeFile(sqlFile,sql,{flag:'wx'});results.push({environment:p.environment,ref:p.ref,ledger:p.ledger,file:sqlFile,sha256:sha(sql),forwardSHA256:p.forwardSHA256,preparedOnly:true});
 }else{const plan=JSON.parse(await readFile(out+'/ROLLBACK-MANIFEST.json','utf8')).results.find(x=>x.environment===p.environment),sql=await readFile(sqlFile,'utf8');if(sha(sql)!==plan.sha256||!sql.endsWith('ROLLBACK;\n'))throw Error('Frozen rollback drift');const before=(await query(p.ref,identity,true))[0];if(before.engine!=='170006'||before.ledger!==p.ledger||before.latest!=='20261005080000')throw Error('Actual native target drift');await writeFile(privateRoot+'/FVI-LEGACY-ROLE-'+p.environment+'-ROLLBACK-INTENT-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),ref:p.ref,before,sourceSHA256:sha(sql),committed:false},null,2),{flag:'wx'});const execution=await query(p.ref,sql,false),after=(await query(p.ref,identity,true))[0];if(JSON.stringify(before)!==JSON.stringify(after)||execution[0]?.old_rows_preserved!==true)throw Error('Actual rollback/protected data differs');const file=privateRoot+'/FVI-LEGACY-ROLE-'+p.environment+'-ROLLBACK-RECEIPT-'+Date.now()+'.json';await writeFile(file,JSON.stringify({at:new Date().toISOString(),environment:p.environment,ref:p.ref,sourceSHA256:sha(sql),before,execution,after,rollbackPassed:true,committed:false},null,2),{flag:'wx'});results.push({environment:p.environment,ref:p.ref,ledger:after.ledger,sourceSHA256:sha(sql),rollbackPassed:true,protectedRelations:execution[0].protected_relations,protectedRows:execution[0].protected_rows,receipt:file,committed:false});}
 console.log(JSON.stringify(results.at(-1)));
}const file=phase==='prepare'?out+'/ROLLBACK-MANIFEST.json':'docs/evidence/FVI_LEGACY_ROLE_ROLLBACK_2026-10-05-'+Date.now()+'.json';await writeFile(file,JSON.stringify({at:new Date().toISOString(),phase,results,noSQLCommit:true},null,2),{flag:'wx'});
